create or replace function public.weekly_top_students() returns table(rank bigint, display_name text, target_exam text, xp integer) language sql stable security definer set search_path=public as $$ select row_number() over(order by sum(x.points) desc, min(x.created_at) asc) as rank, coalesce(nullif(p.name,''),'Student') as display_name, p.target_exam, sum(x.points)::integer as xp from public.xp_events x join public.profiles p on p.id=x.user_id where x.created_at >= date_trunc('week', now()) and x.created_at < date_trunc('week', now()) + interval '7 days' group by p.id,p.name,p.target_exam order by sum(x.points) desc, min(x.created_at) asc limit 20 $$;
revoke all on function public.weekly_top_students() from public, anon;
grant execute on function public.weekly_top_students() to authenticated;
